async function mapSearch(){
 const q=$('atlasMapSearch').value.trim();if(!q)return;
 notice('atlasMapStatus','Konum aranıyor…');const resultBox=$('atlasMapResults');if(resultBox)resultBox.innerHTML='';
 try{
  const cacheKey=q.toLocaleLowerCase('tr-TR');
  let rows=state.searchCache.get(cacheKey);
  if(!rows){
   const wait=Math.max(0,1100-(Date.now()-state.lastSearchAt));
   if(wait)await new Promise(resolve=>setTimeout(resolve,wait));
   state.lastSearchAt=Date.now();
   rows=await api('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=6&addressdetails=1&q='+encodeURIComponent(q));
   state.searchCache.set(cacheKey,rows);
  }
  if(!rows.length){notice('atlasMapStatus','Konum bulunamadı. Farklı bir şehir, ülke veya yer adı dene.');return}
  initGlobe();let waitCount=0;
  const fly=()=>{
   if(!state.globe){if(waitCount++<40&&state.globeLoading){setTimeout(fly,180);return}notice('atlasMapStatus','3D harita henüz hazır değil. Yeniden deneyebilirsin.');return}
   const C=window.Cesium,viewer=state.globe;removeEntities(state.searchEntities);
   rows.forEach(x=>{
    const lon=Number(x.lon),lat=Number(x.lat),label=x.name||x.display_name.split(',')[0];if(!Number.isFinite(lon)||!Number.isFinite(lat))return;
    const entity=viewer.entities.add({name:label,description:esc(x.display_name),position:C.Cartesian3.fromDegrees(lon,lat,0),
     point:{pixelSize:12,color:C.Color.fromCssColorString('#b7dc79'),outlineColor:C.Color.WHITE,outlineWidth:2,heightReference:C.HeightReference.CLAMP_TO_GROUND},
     label:{text:label,font:'13px sans-serif',fillColor:C.Color.WHITE,outlineColor:C.Color.BLACK,outlineWidth:3,style:C.LabelStyle.FILL_AND_OUTLINE,pixelOffset:new C.Cartesian2(0,-23),disableDepthTestDistance:Number.POSITIVE_INFINITY}});
    entity.show=state.searchLayerVisible;state.searchEntities.push(entity);
   });
   const first=rows[0],bbox=(first.boundingbox||[]).map(Number);let height=900000;
   if(bbox.length===4&&bbox.every(Number.isFinite)){const span=Math.max(Math.abs(bbox[1]-bbox[0]),Math.abs(bbox[3]-bbox[2]));height=Math.max(45000,Math.min(11000000,span*115000))}
   viewer.camera.flyTo({destination:C.Cartesian3.fromDegrees(Number(first.lon),Number(first.lat),height),duration:2.1});
   if(resultBox)resultBox.innerHTML=rows.map((r,i)=>`<button type="button" class="atlas-map-result" data-map-result="${i}"><strong>${esc(r.name||r.display_name.split(',')[0])}</strong><small>${esc(r.display_name)}</small></button>`).join('');
   resultBox?.querySelectorAll('[data-map-result]').forEach(b=>b.addEventListener('click',()=>{
    const r=rows[Number(b.dataset.mapResult)];viewer.camera.flyTo({destination:C.Cartesian3.fromDegrees(Number(r.lon),Number(r.lat),Math.max(45000,height*.6)),duration:1.5});
    showPickedPoint({lon:Number(r.lon),lat:Number(r.lat),height:0});
   }));
   notice('atlasMapStatus',`${rows.length} konum bulundu · OpenStreetMap / Nominatim.`);
  };fly();
 }catch(e){
  const message=String(e?.message||'');
  notice('atlasMapStatus',/429/.test(message)?'Konum servisi kısa süreli istek sınırına ulaştı. Biraz bekleyip tekrar dene.':'Konum araması başarısız oldu. Bağlantıyı kontrol edip tekrar dene.');
 }
}
