function openProjectModal(id=null,category=null){
 const existing=id?projects.find(p=>p.id===id):null;
 $("modalTitle").textContent=existing?"Projeyi dÃƒÂ¼zenle":"Yeni proje oluÃ…Å¸tur";
 $("modalContent").innerHTML=`
  <p>${existing?"Proje bilgilerini gÃƒÂ¼ncelle.":"Yeni fikrini bir projeye dÃƒÂ¶nÃƒÂ¼Ã…Å¸tÃƒÂ¼r. Proje bilgilerini daha sonra deÃ„Å¸iÃ…Å¸tirebilirsin."}</p>
  <label class="form-label" for="projectNameInput">Proje adÃ„Â±</label>
  <input class="modal-input" id="projectNameInput" maxlength="70" placeholder="Ãƒâ€“rn. Yeni marka projem" value="${escapeAttr(existing?.name||"")}">
  <label class="form-label" for="projectCategoryInput">Proje kategorisi</label>
  <select class="modal-select" id="projectCategoryInput">
   ${Object.keys(categories).map(c=>`<option ${((existing?.category||category)===c)?"selected":""}>${c}</option>`).join("")}
  </select>
  <label class="form-label" for="projectDescriptionInput">KÃ„Â±sa aÃƒÂ§Ã„Â±klama</label>
  <textarea class="modal-input" id="projectDescriptionInput" maxlength="250" rows="3" placeholder="Bu projede ne geliÃ…Å¸tirmek istiyorsun?">${escapeHTML(existing?.description||"")}</textarea>
  <button class="primary" id="saveProjectButton">${existing?"DeÃ„Å¸iÃ…Å¸iklikleri kaydet":"Projeyi oluÃ…Å¸tur"}</button>`;

 $("modalOverlay").classList.add("show");
 $("saveProjectButton").onclick=()=>{
  const name=$("projectNameInput").value.trim();
  const cat=$("projectCategoryInput").value;
  const description=$("projectDescriptionInput").value.trim();

  if(!name){
   alert("LÃƒÂ¼tfen proje adÃ„Â±na bir isim yaz.");
   $("projectNameInput").focus();
   return;
  }

  if(existing){
   existing.name=name;
   existing.category=cat;
   existing.description=description;
   existing.updatedAt=Date.now();
   saveProjects();
   $("modalOverlay").classList.remove("show");
   openProject(existing.id);
  }else{
   const project={
    id:makeId(),name,category:cat,description,
    createdAt:Date.now(),updatedAt:Date.now(),
    messages:[],notes:""
   };
   projects.unshift(project);
   saveProjects();
   $("modalOverlay").classList.remove("show");
   openProject(project.id);
  }
 };
}

/* PROJECT STUDIO Ã¢â‚¬â€ proje hedefi, yol haritasÃ„Â± ve gÃƒÂ¶rev takibi */
function ensureProjectStudio(project){
 if(!project.studio||typeof project.studio!=="object")project.studio={goal:"",milestones:[],tasks:[]};
 if(!Array.isArray(project.studio.milestones))project.studio.milestones=[];
 if(!Array.isArray(project.studio.tasks))project.studio.tasks=[];
 return project.studio;
}
function saveProjectStudio(){
 const p=getCurrentProject();
 if(!p)return;
 p.updatedAt=Date.now();
 saveProjects();
 renderProjectStudio(p);
}
function renderProjectStudio(project){
 const studio=ensureProjectStudio(project);
 const goal=$("psGoal");
 if(goal&&goal.value!==studio.goal)goal.value=studio.goal||"";
 const milestoneList=$("psMilestoneList"),taskList=$("psTaskList");
 if(!milestoneList||!taskList)return;
 milestoneList.innerHTML="";
 taskList.innerHTML="";
 const makeEmpty=(container,message)=>{
  const empty=document.createElement("div");empty.className="ps-empty";empty.textContent=message;container.appendChild(empty);
 };
 if(!studio.milestones.length)makeEmpty(milestoneList,"Projenin aÃ…Å¸amalarÃ„Â±nÃ„Â± burada sÃ„Â±rala.");
 studio.milestones.forEach((item,index)=>{
  const row=document.createElement("div");row.className="ps-list-row"+(item.done?" is-done":"");
  const check=document.createElement("button");check.type="button";check.className="ps-check";check.setAttribute("aria-label",item.done?"AÃ…Å¸amayÃ„Â± yeniden aÃƒÂ§":"AÃ…Å¸amayÃ„Â± tamamla");check.textContent=item.done?"Ã¢Å“â€œ":"";
  check.onclick=()=>{item.done=!item.done;saveProjectStudio();};
  const label=document.createElement("span");label.className="ps-row-label";label.textContent=item.title;
  const remove=document.createElement("button");remove.type="button";remove.className="ps-remove";remove.textContent="Ãƒâ€”";remove.setAttribute("aria-label","AÃ…Å¸amayÃ„Â± sil");
  remove.onclick=()=>{studio.milestones.splice(index,1);saveProjectStudio();};
  row.append(check,label,remove);milestoneList.appendChild(row);
 });
 if(!studio.tasks.length)makeEmpty(taskList,"Ã„Â°lk gÃƒÂ¶revini ekleyerek ilerlemeyi baÃ…Å¸lat.");
 studio.tasks.forEach((item,index)=>{
  const row=document.createElement("div");row.className="ps-list-row"+(item.done?" is-done":"");
  const check=document.createElement("button");check.type="button";check.className="ps-check";check.setAttribute("aria-label",item.done?"GÃƒÂ¶revi yeniden aÃƒÂ§":"GÃƒÂ¶revi tamamla");check.textContent=item.done?"Ã¢Å“â€œ":"";
  check.onclick=()=>{item.done=!item.done;saveProjectStudio();};
  const label=document.createElement("span");label.className="ps-row-label";label.textContent=item.title;
  const remove=document.createElement("button");remove.type="button";remove.className="ps-remove";remove.textContent="Ãƒâ€”";remove.setAttribute("aria-label","GÃƒÂ¶revi sil");
  remove.onclick=()=>{studio.tasks.splice(index,1);saveProjectStudio();};
  row.append(check,label,remove);taskList.appendChild(row);
 });
 const total=studio.tasks.length+studio.milestones.length;
 const done=studio.tasks.filter(x=>x.done).length+studio.milestones.filter(x=>x.done).length;
 const pct=total?Math.round(done/total*100):0;
 $("psProgressValue").textContent=pct+"%";
 $("psProgressBar").style.width=pct+"%";
 $("psProgressCount").textContent=done+" / "+total+" tamamlandÃ„Â±";
 $("psProgressCaption").textContent=total?(pct===100?"Harika! Bu projenin tÃƒÂ¼m adÃ„Â±mlarÃ„Â± tamamlandÃ„Â±.":"AdÃ„Â±m adÃ„Â±m ilerliyorsun."):"Ã„Â°lk adÃ„Â±mÃ„Â±nÃ„Â± ekleyerek baÃ…Å¸la.";
 $("psMilestoneCount").textContent=studio.milestones.length;
 $("psTaskCount").textContent=studio.tasks.length;
 $("psDoneCount").textContent=done;
}
