function findRelevantProjectContext(prompt){
 const query=String(prompt||"").toLocaleLowerCase("tr-TR");
 const normalizedQuery=query.replace(/[Ã„Â±Ã„Â°]/g,"i");
 const projectIntent=/\b(proje|projeyi|projem|projeme|tozra|uygulama|ÃƒÂ¼rÃƒÂ¼nÃƒÂ¼m|ÃƒÂ¼rÃƒÂ¼n)\b/.test(query);
 if(!projectIntent)return "";

 const candidates=Array.isArray(projects)?projects:[];
 const normalize=value=>String(value||"").trim().toLocaleLowerCase("tr-TR").replace(/[Ã„Â±Ã„Â°]/g,"i");
 const named=candidates.find(project=>{
  const name=normalize(project.name);
  return name.length>=3 && normalizedQuery.includes(name);
 });
 const tozraProject=candidates.find(project=>normalize(project.name)==="tozra");
 const active=getCurrentProject();

 const selected=named ||
  (/\btozra\b/.test(query) ? tozraProject : null) ||
  (active && /\b(aktif proje|bu proje|mevcut projem|projem)\b/.test(query) ? active : null) ||
  (candidates.length===1 ? candidates[0] : null);

 // TOZRA is the app's own product profile. Supply it even when the user
 // has not created a separate project card in the workspace.
 const baseline=/\btozra\b/.test(query) ? buildTozraBaselineContext() : "";
 if(!selected){
  return baseline;
 }

 const savedContext=buildProjectContext(selected);
 const combined=[baseline,savedContext].filter(Boolean).join("\n\n");
 console.info("[TOZRA project memory] Context selected.",{
  projectName:selected.name,
  projectId:selected.id,
  contextLength:combined.length,
  baselineIncluded:Boolean(baseline)
 });
 return combined.slice(0,10000);
}

