function addFiles(files,kind,list,areaId){
 const selected=Array.from(files);
 if(list.length+selected.length>15){
  alert("Bir mesajda fotoÃ„Å¸raf ve videolar dahil en fazla 15 medya ekleyebilirsin.");
  return;
 }
 for(const file of selected){
  if(kind==="image"&&!["image/jpeg","image/png","image/webp"].includes(file.type)){
   alert("JPG, PNG veya WEBP fotoÃ„Å¸raf seÃƒÂ§.");
   continue;
  }
  if(kind==="video"&&!file.type.startsWith("video/")){
   alert("GeÃƒÂ§erli bir video seÃƒÂ§.");
   continue;
  }
  if(file.size>40*1024*1024){
   alert("Dosya boyutu 40 MB sÃ„Â±nÃ„Â±rÃ„Â±nÃ„Â± aÃ…Å¸Ã„Â±yor.");
   continue;
  }
  list.push({file,kind,url:URL.createObjectURL(file)});
 }
 renderAttachmentsFor(list,areaId);
}
function clearFiles(list,areaId){
 list.forEach(a=>URL.revokeObjectURL(a.url));
 list.length=0;
 renderAttachmentsFor(list,areaId);
}
function imageToDataURL(file,maxSide=800,quality=.52){
 return new Promise((resolve,reject)=>{
  const img=new Image();
  const url=URL.createObjectURL(file);
  img.onload=()=>{
   const scale=Math.min(1,maxSide/Math.max(img.width,img.height));
   const canvas=document.createElement("canvas");
   canvas.width=Math.max(1,Math.round(img.width*scale));
   canvas.height=Math.max(1,Math.round(img.height*scale));
   const ctx=canvas.getContext("2d");
   ctx.drawImage(img,0,0,canvas.width,canvas.height);
   URL.revokeObjectURL(url);
   resolve(canvas.toDataURL("image/jpeg",quality));
  };
  img.onerror=()=>{
   URL.revokeObjectURL(url);
   reject(new Error("FotoÃ„Å¸raf okunamadÃ„Â±."));
  };
  img.src=url;
 });
}
function formatTime(seconds){
 const safe=Math.max(0,Math.floor(seconds));
 return String(Math.floor(safe/60)).padStart(2,"0")+":"+String(safe%60).padStart(2,"0");
}
function videoToFrames(file,count=3){
 return new Promise((resolve,reject)=>{
  const video=document.createElement("video");
  const url=URL.createObjectURL(file);
  video.preload="auto";
  video.muted=true;
  video.playsInline=true;
  let finished=false;

  const finish=()=>{
   if(finished)return;
   finished=true;
   video.onloadeddata=null;
   video.onerror=null;
   URL.revokeObjectURL(url);
   video.removeAttribute("src");
   video.load();
  };

  video.onerror=()=>{
   finish();
   reject(new Error("Video okunamadÃ„Â±."));
  };

  video.onloadeddata=async()=>{
   try{
    const duration=video.duration;
    if(!Number.isFinite(duration)||duration<=0)throw new Error("Video sÃƒÂ¼resi okunamadÃ„Â±.");
    const fractions=Array.from({length:count},(_,i)=>(i+1)/(count+1));
    const frames=[];

    for(const f of fractions){
     const target=Math.min(duration*f,Math.max(0,duration-.05));
     await new Promise((res,rej)=>{
      let settled=false;
      const timer=setTimeout(()=>{
       if(!settled){settled=true;rej(new Error("Video karesi alÃ„Â±namadÃ„Â±."))}
      },12000);
      video.addEventListener("seeked",()=>{
       if(settled)return;
       settled=true;
       clearTimeout(timer);
       res();
      },{once:true});
      try{
       video.currentTime=target;
       if(Math.abs(video.currentTime-target)<.01&&video.readyState>=2){
        if(!settled){settled=true;clearTimeout(timer);res()}
       }
      }catch(e){
       clearTimeout(timer);
       rej(e);
      }
     });

     const scale=Math.min(1,560/Math.max(video.videoWidth,video.videoHeight));
     const canvas=document.createElement("canvas");
     canvas.width=Math.max(1,Math.round(video.videoWidth*scale));
     canvas.height=Math.max(1,Math.round(video.videoHeight*scale));
     const ctx=canvas.getContext("2d");
     if(!ctx)throw new Error("Video karesi iÃ…Å¸lenemedi.");
     ctx.drawImage(video,0,0,canvas.width,canvas.height);
     frames.push({data:canvas.toDataURL("image/jpeg",.42),time:target});
    }

    finish();
    resolve({frames,duration,name:file.name});
   }catch(e){
    finish();
    reject(e);
   }
  };
  video.src=url;
  video.load();
 });
}
async function prepareMedia(list){
 const images=[],videoFrames=[],timeline=[];
 const imageItems=list.filter(item=>item.kind==="image");
 const videoItems=list.filter(item=>item.kind==="video");
 const maxVisionImages=3;
 if(imageItems.length>maxVisionImages){
  throw new Error("TOZRA Ã…Å¸u anda bir istekte en fazla 3 fotoÃ„Å¸rafÃ„Â± birlikte analiz edebiliyor. LÃƒÂ¼tfen fotoÃ„Å¸raflarÃ„Â± 3'erli gruplar hÃƒÂ¢linde gÃƒÂ¶nder.");
 }
 const frameBudget=Math.max(0,maxVisionImages-imageItems.length);
 if(videoItems.length>frameBudget){
  throw new Error("Bu istekteki fotoÃ„Å¸raf ve videolarÃ„Â±n her birine en az bir analiz karesi ayÃ„Â±rmak mÃƒÂ¼mkÃƒÂ¼n deÃ„Å¸il. En fazla 3 medya dosyasÃ„Â± seÃƒÂ§ip tekrar dene.");
 }
 for(const item of imageItems) images.push(await imageToDataURL(item.file));
 if(videoItems.length&&frameBudget>0){
  const base=Math.floor(frameBudget/videoItems.length);
  let remainder=frameBudget%videoItems.length;
  for(let index=0;index<videoItems.length;index++){
   const item=videoItems[index];
   const count=base+(remainder>0?1:0);
   if(remainder>0)remainder--;
   if(count<=0)continue;
   const result=await videoToFrames(item.file,count);
   timeline.push({name:result.name,duration:result.duration,frames:result.frames.map((f,i)=>({index:i+1,time:f.time}))});
   videoFrames.push(...result.frames.map(f=>f.data));
  }
 }
 let timelineText="";
 if(timeline.length){
  timelineText="\n\n[TOZRA VISION - KRONOLOJÃ„Â°K VÃ„Â°DEO KARELERÃ„Â°]\n";
  timeline.forEach(v=>{
   timelineText+="\nVideo: "+v.name+"\nSÃƒÂ¼re: "+v.duration.toFixed(2)+" saniye\n";
   v.frames.forEach(f=>{timelineText+="Kare "+f.index+": "+formatTime(f.time)+" zamanÃ„Â±nda alÃ„Â±nmÃ„Â±Ã…Å¸tÃ„Â±r.\n";});
  });
  timelineText+="\nTÃƒÂ¼m fotoÃ„Å¸raflarÃ„Â± ve video karelerini birlikte deÃ„Å¸erlendir. Her videonun karelerini kendi zaman sÃ„Â±rasÃ„Â±na gÃƒÂ¶re yorumla. FarklÃ„Â± videolarÃ„Â± birbirine karÃ„Â±Ã…Å¸tÃ„Â±rma. YalnÃ„Â±zca ÃƒÂ¶rneklenen karelerin desteklediÃ„Å¸i gÃƒÂ¶zlemleri belirt; videonun sesini veya ÃƒÂ¶rneklenmeyen anlarÃ„Â±nÃ„Â± analiz ettiÃ„Å¸ini iddia etme. Benzer/tekrarlanan kareleri ve gÃƒÂ¶zlemlenebilen sahne deÃ„Å¸iÃ…Å¸imlerini belirt.";
 }
 return {images,videoFrames,timelineText};
}
