/* TOZRA tema tercihi: profil ekranÃ„Â±ndan seÃƒÂ§ilir ve cihazda saklanÃ„Â±r. */
function getTozraTheme(){return localStorage.getItem("tozra-theme") === "dark" ? "dark" : "light";}
function setTozraTheme(theme){
 const selected=theme==="dark"?"dark":"light";
 document.documentElement.dataset.tozraTheme=selected;
 document.documentElement.style.colorScheme=selected;
 localStorage.setItem("tozra-theme",selected);
 const meta=document.querySelector('meta[name="theme-color"]');
 if(meta)meta.content=selected==="dark"?"#151b17":"#f5f3ed";
}
setTozraTheme(getTozraTheme());

/* Vurgu rengi: bÃƒÂ¼tÃƒÂ¼n arayÃƒÂ¼zde ortak deÃ„Å¸iÃ…Å¸kenlerle uygulanÃ„Â±r ve cihazda saklanÃ„Â±r. */
const TOZRA_ACCENTS={
 lime:{main:"#a8c77b",soft:"#edf4e2",deep:"#607d3b",dark:"#c5df98"},
 forest:{main:"#4f936b",soft:"#e4f1e8",deep:"#286143",dark:"#82c69a"},
 ocean:{main:"#5798c8",soft:"#e5f1fa",deep:"#326d9b",dark:"#8bc4ee"},
 plum:{main:"#9a78bd",soft:"#f0e9f7",deep:"#705091",dark:"#c2a4df"}
};
function getTozraAccent(){const v=localStorage.getItem("tozra-accent");return TOZRA_ACCENTS[v]?v:"lime";}
function setTozraAccent(name){
 const key=TOZRA_ACCENTS[name]?name:"lime",c=TOZRA_ACCENTS[key],root=document.documentElement;
 root.dataset.tozraAccent=key;
 root.style.setProperty("--accent",c.main);
 root.style.setProperty("--accent-soft",c.soft);
 root.style.setProperty("--accent-deep",c.deep);
 root.style.setProperty("--tozra-accent",c.main);
 root.style.setProperty("--tozra-accent-soft",c.soft);
 root.style.setProperty("--tozra-accent-deep",c.deep);
 root.style.setProperty("--tozra-accent-dark",c.dark);
 /* AÃƒÂ§Ã„Â±lÃ„Â±Ã…Å¸ animasyonu da seÃƒÂ§ilen vurgu rengini anÃ„Â±nda takip eder. */
 root.style.setProperty("--splash-accent",c.main);
 root.style.setProperty("--splash-accent-light",c.dark);
 root.style.setProperty("--splash-accent-deep",c.deep);
 root.style.setProperty("--splash-accent-soft",c.soft);
 /* Ana ekrandaki TOZRA orbit animasyonu da aktif vurgu rengini takip eder. */
 root.style.setProperty("--home-accent",c.main);
 root.style.setProperty("--home-accent-soft",c.soft);
 root.style.setProperty("--home-accent-deep",c.deep);
 root.style.setProperty("--home-accent-light",c.dark);
 localStorage.setItem("tozra-accent",key);
 const meta=document.querySelector('meta[name="theme-color"]');
 if(meta)meta.content=getTozraTheme()==="dark"?"#151b17":c.soft;
}
setTozraAccent(getTozraAccent());

