function addLink(input){
 const url=prompt("Eklemek istediÃ„Å¸in baÃ„Å¸lantÃ„Â±yÃ„Â± yaz:");
 if(!url)return;

 let parsed;
 try{parsed=new URL(url)}
 catch(e){
  alert("LÃƒÂ¼tfen geÃƒÂ§erli bir baÃ„Å¸lantÃ„Â± gir.");
  return;
 }

 if(!["http:","https:"].includes(parsed.protocol)){
  alert("YalnÃ„Â±zca http veya https baÃ„Å¸lantÃ„Â±larÃ„Â± kullanÃ„Â±labilir.");
  return;
 }

 input.value+=(input.value?"\n":"")+"BaÃ„Å¸lantÃ„Â±: "+parsed.href;
 input.focus();
}


