async function refreshAccountData(){
 await TozraAuth.ensureAvatar?.();
 if (window.TozraCloudSync) await TozraCloudSync.init(true);
 conversation=[]; conversations=[]; projects=[];
 loadHistory();
 loadProjects();
 if (typeof taskItems !== "undefined") {
  const restored=safeRead(TASKS_KEY,{tasks:[],events:[]});
  if(restored && Array.isArray(restored.tasks) && Array.isArray(restored.events)) taskItems=restored;
  if(typeof renderTasksCalendar === "function") renderTasksCalendar();
 }
 window.dispatchEvent(new CustomEvent("tozra-account-data-refreshed"));
 TozraAuth.updateAccountUI();
 updateDashboardStats();
}
window.addEventListener("pageshow", async ()=>{
 // iOS PWA/Safari may restore a page from the back-forward cache; refresh the
 // in-memory auth snapshot from Supabase's persistent localStorage session.
 try { await TozraAuth.init(); } catch (error) { console.warn("TOZRA oturum geri yÃƒÂ¼kleme:", error); }
});
window.addEventListener("visibilitychange", async ()=>{
 if(document.visibilityState !== "visible") return;
 try { await TozraAuth.init(); } catch (error) { console.warn("TOZRA oturum yenileme:", error); }
});
window.addEventListener("load", async ()=>{
 await TozraAuth.init();
 await refreshAccountData();
 if(TozraAuth.getSession() && $("splash")){
  // A successful login/redirect must enter the workspace directly, not replay the login splash.
  let justAuthenticated=false;
  try{justAuthenticated=sessionStorage.getItem("tozra-authenticated-entry")==="1";}catch(e){}
  if(justAuthenticated)finishSplash();
  else finishSplash();
 }
 // Guests remain on the animated opening screen and choose Login or Sign up below.
});

/* SERVICE WORKER */
if("serviceWorker" in navigator){
 window.addEventListener("load",()=>{
  navigator.serviceWorker.register("/sw.js").catch(console.error);
 });
}
