   const project={id:typeof window.makeId==='function'?window.makeId():Date.now().toString(36),name,category:active==='image'||active==='design'?'GÃƒÂ¶rsel stÃƒÂ¼dyo':active==='video'?'Video stÃƒÂ¼dyo':active==='writing'||active==='campaign'?'Ã„Â°ÃƒÂ§erik ÃƒÂ¼retimi':'Fikir geliÃ…Å¸tirme',description:brief.slice(0,250),createdAt:Date.now(),updatedAt:Date.now(),messages:[],notes:'CREATIVE STUDIO BRIEF\n\n'+brief+'\n\nHedef kitle: '+((byId('csAudience')?.value||'').trim()||'Belirtilmedi')+'\nYaratÃ„Â±cÃ„Â± yaklaÃ…Å¸Ã„Â±m: '+(byId('csTone')?.value||'Belirtilmedi')+(active==='video'?'\n\nVIDEO AYARLARI\nPlatform: '+(byId('csVideoPlatform')?.value||'YouTube')+'\nSÃƒÂ¼re: '+(byId('csVideoDuration')?.value||'30 saniye')+'\nGÃƒÂ¶rÃƒÂ¼ntÃƒÂ¼ oranÃ„Â±: '+(byId('csVideoRatio')?.value||'16:9 yatay')+'\nSahne sayÃ„Â±sÃ„Â±: '+(byId('csVideoScenes')?.value||'5'):'')};
   projects.unshift(project);
