 let marketCategory='all',marketOnlyFavorites=false,marketDetail=null;
 const allProducts=()=>[...templates,...marketState.uploads];
 function marketSave(){write('tozra-market-v1',marketState)}
 let marketRemoteLoaded=false,marketRemoteLoading=false,marketIsAdmin=false,marketAdminChecked=false;
 async function marketCheckAdmin(){if(marketAdminChecked)return marketIsAdmin;marketAdminChecked=true;const client=TozraAuth.getClient(),userId=TozraAuth.userId();if(!client||userId==='guest')return false;try{const {data,error}=await client.from('market_admins').select('user_id').eq('user_id',userId).maybeSingle();if(error)throw error;marketIsAdmin=!!data;$('marketAdminOpen').hidden=!marketIsAdmin;return marketIsAdmin}catch(error){console.warn('Market admin kontrolÃƒÂ¼:',error);return false}}
 async function marketAdminLoad(){if(!await marketCheckAdmin()){alert('Bu alan yalnÃ„Â±zca yetkili TOZRA yÃƒÂ¶neticilerine aÃƒÂ§Ã„Â±ktÃ„Â±r.');return}const client=TozraAuth.getClient(),list=$('marketAdminList');list.innerHTML='<div class="market-admin-empty">Ã„Â°nceleme kuyruÃ„Å¸u yÃƒÂ¼kleniyorÃ¢â‚¬Â¦</div>';try{const {data,error}=await client.from('market_templates').select('*').eq('status','pending').order('created_at',{ascending:true}).limit(100);if(error)throw error;if(!data?.length){list.innerHTML='<div class="market-admin-empty">Bekleyen ÃƒÂ¼rÃƒÂ¼n bulunmuyor.</div>';return}list.innerHTML=data.map(row=>`<article class="market-admin-item"><div><strong>${esc(row.title)}</strong><small>${esc(cats[row.category]||row.category||'Kategori yok')} Ã‚Â· ${esc(row.is_free?'ÃƒÅ“cretsiz':(row.price+' '+(row.currency||'TRY')))} Ã‚Â· ${new Date(row.created_at).toLocaleString('tr-TR')}</small><small>${esc(row.description||'AÃƒÂ§Ã„Â±klama yok')}</small></div><div class="market-admin-actions"><button type="button" data-market-preview="${esc(row.id)}">DosyayÃ„Â± kontrol et</button><button type="button" class="approve" data-market-approve="${esc(row.id)}">Onayla</button><button type="button" class="reject" data-market-reject="${esc(row.id)}">Reddet</button></div></article>`).join('');list.querySelectorAll('[data-market-preview]').forEach(b=>b.onclick=()=>marketAdminPreview(data.find(r=>r.id===b.dataset.marketPreview)));list.querySelectorAll('[data-market-approve]').forEach(b=>b.onclick=()=>marketAdminSetStatus(b.dataset.marketApprove,'published'));list.querySelectorAll('[data-market-reject]').forEach(b=>b.onclick=()=>marketAdminSetStatus(b.dataset.marketReject,'rejected'));}catch(error){console.error('Market inceleme kuyruÃ„Å¸u:',error);list.innerHTML=`<div class="market-admin-empty">YÃƒÂ¼klenemedi: ${esc(error.message||'Bilinmeyen hata')}</div>`}}
 async function marketAdminPreview(row){if(!row)return;try{const {data,error}=await TozraAuth.getClient().storage.from('market-files').download(row.file_path);if(error)throw error;const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.download=row.title.replace(/[^a-zA-Z0-9._-]/g,'_')+'.file';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){alert('Dosya aÃƒÂ§Ã„Â±lamadÃ„Â±: '+(error.message||'Storage eriÃ…Å¸imi kontrol edilmeli.'))}}
