function syncHomePrimaryNav(tab){
 const nav=document.getElementById("homePrimaryNav"); if(!nav)return;
 nav.querySelectorAll("[data-home-tab]").forEach(button=>{
  const active=!!tab&&button.dataset.homeTab===tab;
  button.classList.toggle("selected",active);
  if(active)button.setAttribute("aria-current","page");else button.removeAttribute("aria-current");
 });
 nav.dataset.activeTab=tab||"";
}
