/* AKILLI KARŞILAMA KOMUTU */
function startChatWithPrompt(value){
 const prompt=String(value||"").trim();
 openGeneralChat();
 if(prompt){
  promptInput.value=prompt;
  promptInput.dispatchEvent(new Event("input",{bubbles:true}));
  promptInput.focus();
 }
}

