 if(!p)return;
 if(!confirm('"'+p.name+'" projesini silmek istediğine emin misin? Bu işlem geri alınamaz.'))return;
 projects=projects.filter(x=>x.id!==id);
 saveProjects();
 currentProjectId=null;
